def countMaxAtBothEnds(nums):
    total = 0
    stack = []  # [value, count] pairs, values strictly decreasing from bottom to top
    for x in nums:
        while stack and stack[-1][0] < x:
            stack.pop()
        if stack and stack[-1][0] == x:
            stack[-1][1] += 1
        else:
            stack.append([x, 1])
        total += stack[-1][1]
    return total
